    r"gpro(?:_web)?|gflash(?:_web)?|muse|sonnet|run\d{2,3}|v2a|E7_[A-Za-z0-9_]+|ATTN_[A-Za-z0-9_]+)(?![A-Za-z0-9_])"
)
PLACEHOLDER_RE = re.compile(r"\{\{[A-Z][A-Z0-9_]*\}\}")
